mapper.select:
SELECT

FROM movie


        AND status = #{status}


        AND title LIKE CONCAT(
            REPLACE(REPLACE(REPLACE(#{title}, '!', '!!'), '%', '!%'), '_', '!_'),
            '%'
        ) ESCAPE '!'


        AND release_date >= #{releaseDateFrom}


        AND release_date <= #{releaseDateTo}


        AND publish_at >= #{publishAtFrom}


        AND publish_at <= #{publishAtTo}


ORDER BY

    title
    publish_at
    create_time
    release_date


    DESC
    ASC
, id ASC
